import {summarize,filterRows,monthList,paymentCategories} from './model.mjs';
const app=document.querySelector('#app');
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;
try{const res=await fetch('./data.json',{cache:'no-store'});if(!res.ok)throw Error();data=await res.json();}catch{app.innerHTML='<h1>Revenue</h1><p>The saved report could not be loaded. Reload this page to try again.</p>';throw Error('Snapshot unavailable');}
const months=monthList('2026-01','2026-09');
const label=m=>new Date(`${m}-15T12:00:00Z`).toLocaleString('en-US',{month:'short',year:'numeric',timeZone:'UTC'});
const state={source:'all',start:months[0],end:months.at(-1),currency:'USD'};
const date=v=>new Date(v).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Chicago'});
const money=v=>v===null||v===undefined?'Unavailable':new Intl.NumberFormat('en-US',{style:'currency',currency:state.currency}).format(v/100);
app.outerHTML=`<div class="shell"><aside class="rail"><div class="brand">Q<span style="color:var(--muted)"> / </span><em>Finance</em></div><nav aria-label="Sections"><a href="#overview">Overview</a><a href="#sources">Payment sources</a><a href="#monthly">Monthly detail</a><a href="#definitions">Definitions</a></nav><div class="rail-bottom"><div class="identity"><div class="avatar">QF</div><div>Quentin Flores<br><small>Business reporting</small></div></div>Private workspace<br>Aggregate records only</div></aside><main><header class="topline" id="overview"><div><div class="eyebrow">Business finance</div><h1>Revenue overview</h1></div><span class="private">Owner access only</span></header><div class="muted" style="font-size:14px">2026 payment activity · America/Chicago · USD</div><div class="filters"><label>Business / source<select id="source"><option value="all">All reviewed sources</option><option value="stripe">Just Jarvis LLC · Stripe</option><option value="paypal">Just Jarvis LLC · PayPal</option><option value="skool">Skool communities</option></select></label><label>From month<select id="start">${months.map(m=>`<option value="${m}">${label(m)}</option>`).join('')}</select></label><label>Through month<select id="end">${months.map(m=>`<option value="${m}" ${m===state.end?'selected':''}>${label(m)}${m===months.at(-1)?' · partial':''}</option>`).join('')}</select></label><button id="ytd">2026 YTD</button></div><div id="results" aria-live="polite"></div><section id="definitions" class="panel"><h2>What these numbers mean</h2><dl><dt>Gross receipts</dt><dd>Stripe charge-category amounts plus successful PayPal Express Checkout credits before refunds, disputes and fees. Includes any tax collected in the charge. Sales by brand or product are not yet allocated.</dd><dt>Refunds & disputes</dt><dd>Principal deductions dated when they affect the processor balance. Dispute reversals are shown as separate credits. This is activity by month, not a cohort of sales made in that month.</dd><dt>Processing fees</dt><dd>Fees attached to included Stripe charges and PayPal checkout receipts. Other fees include disputes and the signed net effect of separate fee records, counted once. Fees on excluded payments and withdrawals are also excluded.</dd><dt>Net payment activity</dt><dd>Gross receipts − refunds − disputes + dispute reversals − all included fees. This is not profit, MRR, tax-exclusive revenue, or confirmed money deposited in a bank.</dd><dt>Payouts & financing</dt><dd>Transfers to a bank, financing, repayments, reserve movements and balances are excluded from gross receipts and net payment activity. Payout evidence does not establish bank receipt.</dd><dt>PayPal exclusions</dt><dd>General incoming payments and mass-payment credits are shown as separate evidence pending business classification and overlap review. Pending holds, releases, funding, withdrawals and spending are excluded.</dd><dt>Skool overlap</dt><dd>Skool payouts are reported separately. No Skool amount is added to Stripe or PayPal until original payment references, settlement records and entity ownership establish whether the same receipt is already included.</dd><dt>Missing data</dt><dd>Unavailable means no reconciled amount is available. A zero means no matching event appeared in the retrieved, indexed records; it does not fill the provider coverage gap. September ends at the stated cutoff.</dd></dl><details><summary>Source documentation and refresh</summary><p class="section-sub" style="margin-top:16px">This is a dated, manually refreshed snapshot. Opening or reloading this page does not contact payment providers. The next refresh must collect, validate and privately publish a new snapshot. No recurring collection is configured.</p><p style="font-size:14px"><a href="https://docs.stripe.com/reports/reporting-categories" target="_blank" rel="noreferrer">Stripe reporting categories</a> · <a href="https://developer.paypal.com/reports/reference/t-codes" target="_blank" rel="noreferrer">PayPal transaction event codes</a></p></details></section><footer class="foot"><span>Report prepared ${esc(date(data.prepared_at))} CT</span><span>Amounts in USD · No currency conversion</span></footer></main></div>`;
for(const key of ['source','start','end'])document.getElementById(key).addEventListener('change',e=>{state[key]=e.target.value;if(state.start>state.end){if(key==='start')state.end=state.start;else state.start=state.end;document.getElementById('start').value=state.start;document.getElementById('end').value=state.end;}render();});
document.getElementById('ytd').addEventListener('click',()=>{state.start=months[0];state.end=months.at(-1);document.getElementById('start').value=state.start;document.getElementById('end').value=state.end;render();});
function bridge(r){const row=(name,value,cls='')=>`<div class="bridge-row ${cls}"><span>${name}</span><span>${value}</span></div>`;if(!r)return '<div class="empty">A reconciled payment report is not available for this source.</div>';return row('Gross receipts',money(r.gross))+row('Refunds',`−${money(r.refunds)}`)+row('Disputes',`−${money(r.disputes)}`)+row('Dispute reversals',`+${money(r.reversals)}`)+row('Processing fees',`−${money(r.processing)}`)+row('Other fees',`−${money(r.otherFees)}`,'indent')+row('Net payment activity',money(r.net),'total');}
function render(){
 const selectedMonths=monthList(state.start,state.end);
 const stripeRows=filterRows(data.stripe.rows,state.start,state.end,state.currency);
 const paypalRows=filterRows(data.paypal.rows,state.start,state.end,state.currency);
 const included=state.source!=='skool';
 const activeRows=state.source==='all'?[...stripeRows,...paypalRows]:state.source==='paypal'?paypalRows:stripeRows;
 const r=included?summarize(activeRows):null;
 const sr=summarize(stripeRows),pr=summarize(paypalRows);
 const title=state.source==='stripe'?'Just Jarvis LLC · Stripe':state.source==='all'?'Stripe + PayPal checkout subset':state.source==='paypal'?'Just Jarvis LLC · PayPal checkout subset':'Skool communities';
 const selectedPayouts=data.skool.communities.flatMap(c=>c.currency===state.currency?c.payouts.filter(p=>p.month>=state.start&&p.month<=state.end&&Number.isSafeInteger(p.amount_minor)):[]);
 const payoutSum=selectedPayouts.length?selectedPayouts.reduce((n,p)=>n+p.amount_minor,0):null;
 const rows=selectedMonths.map(m=>({month:m,metrics:included?summarize(activeRows.filter(x=>x.month===m)):null}));
 const max=Math.max(1,...rows.map(x=>x.metrics?.gross||0));
 const coverage=state.source==='stripe'?'Stripe retrieval complete for the reported period. September 14 is a partial day.':state.source==='paypal'?esc(data.paypal.note):state.source==='skool'?esc(data.skool.note):'Partial coverage: includes Stripe and verified PayPal checkout activity. Other PayPal credits and Skool payouts are excluded. Provider cutoffs differ by 82 seconds.';
 const table=`<div class="table-wrap"><table><thead><tr><th>Month</th><th>Gross receipts</th><th>Refunds</th><th>Disputes, net</th><th>All fees</th><th>Net activity</th></tr></thead><tbody>${rows.map(({month,metrics:x})=>`<tr><td>${label(month)}${month==='2026-09'?' <small>partial</small>':''}</td><td>${money(x?.gross)}</td><td>${money(x?.refunds)}</td><td>${money(x?x.disputes-x.reversals:null)}</td><td>${money(x?.fees)}</td><td>${money(x?.net)}</td></tr>`).join('')}</tbody><tfoot><tr><td>Selected period</td><td>${money(r?.gross)}</td><td>${money(r?.refunds)}</td><td>${money(r?r.disputes-r.reversals:null)}</td><td>${money(r?.fees)}</td><td>${money(r?.net)}</td></tr></tfoot></table></div>`;
 const chart=included?`<div class="chart" role="img" aria-label="Monthly gross receipts and net activity; exact values in the monthly detail table">${rows.map(({month,metrics:x})=>`<div class="bar-group"><div class="bars"><div class="bar" style="height:${x.gross/max*100}%" title="${label(month)} gross ${money(x.gross)}"></div><div class="bar net" style="height:${Math.max(0,x.net)/max*100}%" title="${label(month)} net ${money(x.net)}"></div></div><div class="month">${label(month).slice(0,3)}${month==='2026-09'?'*':''}</div></div>`).join('')}</div><p class="chart-note">${state.end==='2026-09'?'* Sep 14 cutoff: Stripe 2:31:21 PM; PayPal 2:29:59 PM CT. ':''}Stripe uses balance-entry dates; PayPal uses transaction initiation dates.</p>`:'<div class="empty">Monthly receipts are unavailable.<br>Missing amounts are not plotted as zero.</div>';
 const paypalEvidence=filterRows(data.paypal.excluded,state.start,state.end,state.currency);
 const sumCode=(code,field)=>paypalEvidence.filter(x=>x.code===code).reduce((a,x)=>a+x[field],0);
 const paypalDetail=`<section class="panel" style="margin-bottom:22px"><h2>PayPal receipts awaiting classification</h2><p class="section-sub" style="margin-top:10px">Actual incoming payment records, excluded from the headline figures. Selected months · USD</p><div class="audit-grid"><div><div class="bridge-row"><span>General payments · T0000</span><span>${money(sumCode('T0000','amount_minor'))}</span></div><div class="bridge-row"><span>Fees on general payments</span><span>${money(-sumCode('T0000','fee_signed_minor'))}</span></div><div class="bridge-row"><span>Mass-payment credits · T0001</span><span>${money(sumCode('T0001','amount_minor'))}</span></div></div><p class="section-sub">Three general-payment notes mention commissions or referrals ($940.36 YTD, regardless of the month filter); that context alone does not complete the classification. The remaining general payments and mass-payment credits need source attribution before inclusion.</p></div></section>`;
 const skoolCards=(data.skool.communities||[]).map(c=>{const payouts=(c.payouts||[]).filter(p=>p.month>=state.start&&p.month<=state.end);const valid=c.currency===state.currency&&payouts.every(p=>Number.isSafeInteger(p.amount_minor));const total=valid?payouts.reduce((a,p)=>a+p.amount_minor,0):null;return `<div class="source panel"><h3>${esc(c.name)}</h3><p>${esc(c.coverage_note||'Payout history reviewed; receipt reconciliation pending.')}</p><div class="source-number">${payouts.length&&valid?money(total):'Unavailable'}</div><small>${payouts.length&&valid?`${payouts.length} observed payout${payouts.length===1?'':'s'} in selected months`:'No confirmed USD payout amount in selected months'}</small><small>${esc(c.entity_note||'Legal entity unconfirmed')} · ${esc(c.currency||'Currency unconfirmed')}</small></div>`;}).join('');
 const outside={};for(const b of stripeRows)if(!paymentCategories.has(b.category))outside[b.category]=(outside[b.category]||0)+b.net_minor;
 document.getElementById('results').innerHTML=`<div class="coverage"><strong>${coverage}</strong></div><section class="metrics"><div class="card"><div class="metric-label">${state.source==='skool'?'Observed payouts':'Gross receipts'} · ${state.currency}</div><div class="number">${money(state.source==='skool'?payoutSum:r?.gross)}</div><small>${state.source==='skool'?'Transfers shown separately; excluded from receipts':esc(title)}</small></div><div class="card primary"><div class="metric-label">Net payment activity · ${state.currency}</div><div class="number">${money(r?.net)}</div><small>After refunds, disputes and included fees</small></div><div class="card"><div class="metric-label">Included fees · ${state.currency}</div><div class="number">${money(r?.fees)}</div><small>${r?`${money(r.processing)} processing + ${money(r.otherFees)} other fees`:'A reconciled fee breakdown is unavailable'}</small></div></section><div class="grid"><section class="panel"><div class="panel-head"><h2>Monthly activity</h2><div class="legend"><span>Gross</span><span>Net</span></div></div>${chart}</section><section class="panel"><div class="panel-head"><h2>Gross to net</h2><span class="tag">${r?'Reconciled':'Incomplete'}</span></div>${bridge(r)}</section></div><section id="sources"><h2 class="section-title">Payment sources</h2><div class="source-grid"><article class="source card"><div class="source-head"><h3>Stripe</h3><span class="pill verified">Verified</span></div><div class="source-number">${money(sr.gross)}</div><p>Just Jarvis LLC · Gross receipts for selected months</p><small>${data.stripe.count.toLocaleString()} balance entries · ${data.stripe.pages} pages, complete YTD retrieval</small><small>Refreshed ${esc(date(data.stripe.retrieved_at))} CT</small></article><article class="source card"><div class="source-head"><h3>PayPal</h3><span class="pill">${esc(data.paypal.label||'Pending')}</span></div><div class="source-number">${money(pr.gross)}</div><p>Just Jarvis LLC payout recipient · Account label: VS STAFFING LLC</p><small>${esc(data.paypal.note)}</small><small>${data.paypal.checked_at?'Checked '+esc(date(data.paypal.checked_at))+' CT':'Reporting access verified; transaction collection pending'}</small></article><article class="source card"><div class="source-head"><h3>Skool</h3><span class="pill">Overlap unresolved</span></div><div class="source-number">Excluded</div><p>AI For Business Mastermind · Real Estate Cheat Codes · Wholesaling Houses101</p><small>${esc(data.skool.note)}</small><small>${data.skool.checked_at?'Checked '+esc(date(data.skool.checked_at))+' CT':'Owner records under review'}</small></article></div></section>${paypalDetail}${skoolCards?`<section><h2 class="section-title">Skool payout evidence</h2><p class="section-sub">Observed transfers, shown separately. These amounts are not added to receipts or net payment activity.</p><div class="source-grid">${skoolCards}</div></section>`:''}<section class="panel" id="monthly"><div class="panel-head"><div><h2>Monthly detail</h2><small>${esc(title)}</small></div><small>${label(state.start)} – ${label(state.end)} · USD</small></div>${table}</section><section class="panel" style="margin:22px 0"><h2>Reconciliation & coverage</h2><div class="audit-grid"><div><div class="bridge-row"><span>Stripe arithmetic</span><span class="tag">Passed</span></div><p class="section-sub" style="margin-top:14px">All category buckets satisfy gross amount minus attached fee equals net. Monthly totals reconcile to the source snapshot. Source counts and pagination are complete.</p><p class="section-sub">PayPal: 150 records across nine pages. The $700 chargeback matches a checkout receipt by original transaction reference. Quentin confirmed Just Jarvis LLC receives Stripe and PayPal payouts. PayPal’s observed account label is VS STAFFING LLC; legal account-name alignment is unverified. Combined figures cover the defined receipt subset, not a full business P&L.</p></div><div><div class="bridge-row"><span>Stripe cutoff</span><span>Sep 14, 2:31 PM CT</span></div><div class="bridge-row"><span>PayPal indexed through</span><span>Sep 14, 2:29:59 PM CT</span></div><div class="bridge-row"><span>Bank reconciliation</span><span>Not available</span></div><div class="bridge-row"><span>Recurring refresh</span><span>Not configured</span></div></div></div><details><summary>Stripe movements excluded from receipts · selected period</summary><div class="table-wrap"><table><thead><tr><th>Source category</th><th>Signed net movement · USD</th></tr></thead><tbody>${Object.entries(outside).map(([k,v])=>`<tr><td>${esc(k.replaceAll('_',' '))}</td><td>${money(v)}</td></tr>`).join('')}</tbody></table></div><p class="chart-note">Signed movements are preserved as reported, including payout reversals. An opening balance and aligned bank records are required to reconcile ending cash.</p></details></section>`;
}
render();
